const {test}=require('node:test');
const assert=require('node:assert/strict');
const fs=require('node:fs'),vm=require('node:vm');
const html=fs.readFileSync(require('node:path').join(__dirname,'../index.html'),'utf8');
const script=fs.readFileSync(require('node:path').join(__dirname,'../core.js'),'utf8')+'\n'+fs.readFileSync(require('node:path').join(__dirname,'../app.js'),'utf8');
function app(options={}){
 const store=options.store||new Map(),elements={},timers=new Map(),windowListeners={},confirmations=[]; let timerID=0; let failWrites=false, failSubmit=false, submitted=0, confirmation=true, failRemove=false;
 const defaults={},tags={},types={},initialHidden={};
 for(const m of html.matchAll(/<(input|select|details|div)[^>]*id="([^"]+)"[^>]*>/g)){
  tags[m[2]]=m[1].toUpperCase(); defaults[m[2]]=m[0].match(/value="([^"]*)"/)?.[1]||'';types[m[2]]=m[0].match(/type="([^"]*)"/)?.[1]||'';initialHidden[m[2]]=/ hidden(?:[ >])/.test(m[0]);
 }
 for(const m of html.matchAll(/<select[^>]*id="([^"]+)"[^>]*>([\s\S]*?)<\/select>/g))defaults[m[1]]=m[2].match(/<option value="([^"]*)"/)?.[1]||'';
 function element(id){if(!elements[id]){let value=defaults[id]||'',markup='';const listeners={},attrs={};elements[id]={id,tagName:tags[id]||'INPUT',type:types[id]||'',checked:false,hidden:initialHidden[id]||false,open:false,validity:{badInput:false},get value(){return value},set value(v){value=String(v)},get innerHTML(){return markup},set innerHTML(v){markup=String(v);for(const m of markup.matchAll(/<input[^>]*id="([^"]+)"[^>]*>/g)){delete elements[m[1]];element(m[1]).value=(m[0].match(/value="([^"]*)"/)?.[1]||'').replace(/&quot;/g,'"').replace(/&#39;/g,"'").replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&amp;/g,'&');}},innerText:'',style:{},setAttribute(k,v){attrs[k]=String(v)},getAttribute:k=>attrs[k]??null,focus(){},select(){},showModal(){this.open=true},close(){this.open=false},classList:{add(){},remove(){}},addEventListener(type,fn){(listeners[type]??=[]).push(fn)},dispatch(type,target=elements[id]){for(const fn of listeners[type]||[])fn({type,target})},appendChild(){},click(){},submit(){if(failSubmit)throw Error('network');submitted++;}};}return elements[id];}
 const calcControls=[...html.slice(html.indexOf('<div id="calc"'),html.indexOf('<div id="history"')).matchAll(/<(?:input|select)[^>]*id="([^"]+)"/g)].map(m=>m[1]);
 const c={document:{getElementById:element,createElement:()=>element('generated'+Math.random()),getElementsByClassName:()=>[],querySelector:()=>element('tab'),querySelectorAll:selector=>selector==='#calc input, #calc select'?calcControls.map(element):[],body:{scrollHeight:0,appendChild(){},removeChild(){}}},window:{scrollTo(){},addEventListener(type,fn){(windowListeners[type]??=[]).push(fn)}},navigator:{},localStorage:{getItem:k=>{if(options.failReadKey===k)throw Error('Read denied');return store.get(k)??null},setItem:(k,v)=>{if(failWrites||options.failWriteKey===k)throw Error('Quota');store.set(k,v)},removeItem:k=>{if(failRemove)throw Error('Remove denied');store.delete(k)}},setTimeout:(fn,delay)=>{const id=++timerID;timers.set(id,{fn,delay});return id},clearTimeout:id=>timers.delete(id),confirm:message=>{confirmations.push(message);return confirmation},Intl,Blob,URL};
 vm.createContext(c);vm.runInContext(script,c);
 return{store,element,confirmations,boot:()=>c.window.onload(),input:id=>element('calc').dispatch('input',element(id)),pagehide:()=>{for(const fn of windowListeners.pagehide||[])fn()},flush:()=>{for(const [id,t] of [...timers]) if(t.delay<=200){timers.delete(id);t.fn()}},run:s=>vm.runInContext(s,c),failWrites:()=>failWrites=true,allowWrites:()=>failWrites=false,failRemove:()=>failRemove=true,confirm:value=>confirmation=value,failSubmit:()=>failSubmit=true,get submitted(){return submitted}};
}
const receipt=(id,extra={})=>({id,date:'05.10.2026',name:'Тест',recipe:'Без мат-в',total:4270,profit:3650,exp:620,workTime:1,...extra});
test('default and material calculations preserve self-employed income',()=>{const a=app();assert.equal(a.run('calculate()'),true);assert.equal(a.run('currentCalc.total'),4270);assert.equal(a.run('currentCalc.profit'),3650);a.element('m-estel').value=60;a.element('m-oxide').value=60;a.run('calculate()');assert.equal(a.run('currentCalc.total'),5057.5);assert.equal(a.run('currentCalc.profit'),3912.5);assert.equal(a.run('currentCalc.rates.pEstel'),7.75);});
test('migration merges and preserves current record on ID conflict',()=>{const a=app();a.store.set('master_calc_palette_history_final',JSON.stringify([receipt(2,{name:'current'})]));a.store.set('palette_m_history',JSON.stringify([receipt(1),receipt(2,{name:'old'})]));a.run('migrateOldData();migrateOldData()');const h=JSON.parse(a.store.get('master_calc_palette_history_final'));assert.equal(h.length,2);assert.equal(h[0].name,'current');assert.ok(a.store.get('master_calc_palette_before_migration'));});
test('invalid existing history is not overwritten',()=>{const a=app();a.store.set('master_calc_palette_history_final','broken');assert.throws(()=>a.run('migrateOldData()'));assert.equal(a.store.get('master_calc_palette_history_final'),'broken');});
test('partial settings use defaults, valid zeros are preserved',()=>{const a=app();a.store.set('master_calc_palette_settings_final',JSON.stringify({hour:0}));assert.equal(a.run('getSettings().hour'),0);assert.equal(a.run('getSettings().pEstel'),7.75);a.element('calc-client-name').value='Тест';assert.equal(a.run('calculate()'),true);assert.equal(a.run('currentCalc.total'),770);});
test('invalid inputs cannot retain a previously valid calculation',()=>{for(const value of ['-1','Infinity','nonsense']){const a=app();a.run('calculate()');a.element('m-estel').value=value;assert.equal(a.run('calculate()'),false);assert.equal(a.run('currentCalc'),null);}const a=app();a.element('cons-count').value='1.5';assert.equal(a.run('calculate()'),false);});
test('repeat preserves zero hours and consumables',()=>{const a=app();a.store.set('master_calc_palette_history_final',JSON.stringify([receipt(1,{raw:{wTime:0,rTime:0,cCount:0,gE:10}})]));a.run('loadReceipt(1)');assert.equal(a.run('currentCalc.raw.wTime'),0);assert.equal(a.run('currentCalc.raw.rTime'),0);assert.equal(a.run('currentCalc.raw.cCount'),0);});
test('save recalculates current fields and prevents double save',()=>{const a=app();a.run('calculate()');a.element('work-time').value=2;a.run('saveData();saveData()');const h=JSON.parse(a.store.get('master_calc_palette_history_final'));assert.equal(h.length,1);assert.equal(h[0].raw.wTime,2);assert.equal(h[0].total,7770);assert.ok(h[0].createdAt);assert.equal(a.submitted,1);});
test('storage failure keeps inputs and current calculation for retry',()=>{const a=app();a.element('calc-client-name').value='Тест';a.run('calculate()');a.failWrites();a.run('saveData()');assert.equal(a.element('calc-client-name').value,'Тест');assert.ok(a.run('currentCalc'));assert.equal(a.submitted,0);});
test('submission failure retains local receipt without duplication on retry',()=>{const a=app();a.run('calculate()');a.failSubmit();a.run('saveData();saveData()');assert.equal(JSON.parse(a.store.get('master_calc_palette_history_final')).length,1);assert.equal(a.run('currentCalc'),null);});
test('import merges duplicates and retains existing receipts',async()=>{const a=app();a.store.set('master_calc_palette_history_final',JSON.stringify([receipt(2)]));const payload={app:'master-calc',schemaVersion:2,history:[receipt(1),receipt(2)],settings:JSON.parse(a.run('JSON.stringify(getSettings())'))};a.run('globalThis.importInput = {files:[],value:"file"}');a.run('importInput').files.push({size:100,text:async()=>JSON.stringify(payload)});await a.run('importBackup(importInput)');assert.equal(JSON.parse(a.store.get('master_calc_palette_history_final')).length,2);assert.ok(a.store.get('master_calc_palette_before_import'));});
test('invalid backup cannot alter history',async()=>{const a=app();const original=JSON.stringify([receipt(1)]);a.store.set('master_calc_palette_history_final',original);a.run('globalThis.importInput = {files:[],value:"file"}');a.run('importInput').files.push({size:100,text:async()=>'{"app":"other"}'});await a.run('importBackup(importInput)');assert.equal(a.store.get('master_calc_palette_history_final'),original);});
test('backup can restore damaged history while preserving original snapshot',async()=>{const a=app();a.store.set('master_calc_palette_history_final','broken');const payload={app:'master-calc',schemaVersion:2,history:[receipt(1)],settings:JSON.parse(a.run('JSON.stringify(getSettings())'))};a.run('globalThis.importInput = {files:[],value:"file"}');a.run('importInput').files.push({size:100,text:async()=>JSON.stringify(payload)});await a.run('importBackup(importInput)');assert.equal(JSON.parse(a.store.get('master_calc_palette_history_final')).length,1);assert.equal(JSON.parse(a.store.get('master_calc_palette_before_import')).master_calc_palette_history_final,'broken');});
test('automatic recalculation uses the latest input after rapid edits',()=>{const a=app();a.run('calculate()');a.element('work-time').value=2;a.run('scheduleCalculation()');assert.equal(a.run('currentCalc'),null);a.element('work-time').value=3;a.run('scheduleCalculation()');a.flush();assert.equal(a.run('currentCalc.total'),11270);assert.equal(a.element('quick-total').innerText,'11270 ₽');});
test('empty intermediate input disables saving quietly and recovers',()=>{const a=app();a.run('calculate()');const toast=a.element('toast').innerText;a.element('work-time').value='';a.run('scheduleCalculation()');a.flush();assert.equal(a.run('currentCalc'),null);assert.equal(a.element('save-receipt').disabled,true);assert.equal(a.element('toast').innerText,toast);assert.ok(a.element('calc-message').innerText);a.element('work-time').value=1;a.run('scheduleCalculation()');a.flush();assert.equal(a.run('currentCalc.total'),4270);assert.equal(a.element('save-receipt').disabled,false);});
test('palette quantities can be entered immediately and cleared without hiding tiles',()=>{const a=app();a.element('m-estel').value=60;a.run('calculate(false,true)');assert.equal(a.run('currentCalc.total'),4967.5);a.run('removeMaterial("estel")');assert.equal(a.element('row-estel').hidden,false);assert.equal(a.run('currentCalc.total'),4270);});
test('5000 receipts render in pages with accurate totals and filtered search',()=>{const a=app();const h=Array.from({length:5000},(_,i)=>receipt(i+1,{name:i%100===0?'Нужный клиент':'Другой клиент'}));a.store.set('master_calc_palette_history_final',JSON.stringify(h));const start=performance.now();a.run('renderHistory()');const duration=performance.now()-start;assert.equal((a.element('history-list').innerHTML.match(/class="history-item"/g)||[]).length,50);assert.equal(a.element('stat-total').innerText,'18250000 ₽');assert.equal(a.element('history-count').innerText,'Показано 50 из 5000');a.run('renderHistory(true)');assert.equal((a.element('history-list').innerHTML.match(/class="history-item"/g)||[]).length,100);a.element('search-history').value='нужный';a.run('scheduleHistorySearch()');a.flush();assert.equal(a.element('history-count').innerText,'Показано 50 из 50');assert.equal(a.element('history-more').hidden,true);assert.equal(a.element('stat-filtered').innerText,'По найденному: 182500 ₽');console.log(`5000 receipts: first page prepared in ${duration.toFixed(1)} ms (Node, without browser layout)`);});
test('alternative uses hourly rent with fixed work and extra expenses',()=>{const a=app();a.element('work-mode').value='fixed';a.element('work-fixed').value=2000;a.element('extra-cost').value=200;a.run('calculate()');assert.equal(a.run('currentCalc.total'),2970);assert.equal(a.run('currentCalc.exp'),820);assert.equal(a.run('currentCalc.profit'),2150);assert.equal(a.run('currentCalc.raw.rentMode'),'hourly');a.element('rent-time').value=2;a.run('calculate()');assert.equal(a.run('currentCalc.total'),3290);});
test('custom package material uses unit price and snapshots its cost',()=>{const a=app();a.run('globalThis.config=getConfig();config.catalog.push({id:"custom-1",name:"Шампунь",unit:"мл",price:1200,pack:1000,archived:false});persistConfig(config);customQuantities={"custom-1":"50"}');a.element('quantity-custom-1').value=50;a.run('calculate()');assert.equal(a.run('currentCalc.total'),4360);assert.equal(a.run('currentCalc.materialLines[0].unitPrice'),1.2);assert.equal(a.run('currentCalc.materialLines[0].cost'),60);});
test('piece material rejects fractional quantities',()=>{const a=app();a.run('globalThis.config=getConfig();config.catalog.push({id:"custom-1",name:"Маска",unit:"шт",price:100,pack:1,archived:false});persistConfig(config);customQuantities={"custom-1":"1.5"}');a.element('quantity-custom-1').value='1.5';assert.equal(a.run('calculate()'),false);});
test('template excludes client name and uses current material rates',()=>{const a=app();a.element('calc-client-name').value='Секретный клиент';a.element('template-name').value='Окрашивание';a.element('m-estel').value=60;a.element('work-mode').value='fixed';a.element('work-fixed').value=2000;a.run('saveTemplate()');const t=JSON.parse(a.store.get('master_calc_palette_config_v3')).templates[0];assert.equal(t.raw.workFixed,2000);assert.ok(!JSON.stringify(t).includes('Секретный'));a.element('service-template').value=t.id;a.store.set('master_calc_palette_settings_final',JSON.stringify({pEstel:10}));a.run('applyTemplate()');assert.equal(a.run('currentCalc.total'),3670);assert.equal(a.run('currentCalc.materialLines[0].unitPrice'),10);});
test('catalog edit archive and reactivation preserve receipt snapshots',()=>{const a=app();a.element('m-estel').value=60;a.run('calculate();saveData()');const original=a.store.get('master_calc_palette_history_final');a.run('editCatalogItem("estel")');a.element('catalog-price').value=1000;a.element('catalog-pack').value=100;a.run('saveCatalogItem();archiveCatalogItem("estel")');assert.equal(a.run('getConfig().catalog.find(i=>i.id==="estel").archived'),true);assert.equal(a.run('materialPrice(getConfig().catalog.find(i=>i.id==="estel"))'),10);a.run('archiveCatalogItem("estel")');assert.equal(a.run('getConfig().catalog.find(i=>i.id==="estel").archived'),false);assert.equal(a.store.get('master_calc_palette_history_final'),original);});
test('monthly analytics include boundaries and exclude unknown dates',()=>{const a=app();a.store.set('master_calc_palette_history_final',JSON.stringify([receipt(1,{date:'01.10.2026'}),receipt(2,{date:'31.10.2026'}),receipt(3,{date:'01.11.2026'}),receipt(4,{date:'unknown'})]));a.element('history-month').value='2026-10';a.run('selectHistoryMonth()');assert.equal(a.element('history-to').value,'2026-10-31');assert.equal(a.element('history-count').innerText,'Показано 2 из 2');assert.ok(a.element('period-stats').innerText.includes('Выручка: 8540'));assert.ok(a.element('period-stats').innerText.includes('исключены'));a.run('resetHistoryPeriod()');assert.equal(a.element('history-count').innerText,'Показано 4 из 4');});
test('v3 backup restores catalog and templates, v2 retains current config',async()=>{const a=app();const config=JSON.parse(a.run('JSON.stringify(getConfig())'));config.catalog.push({id:'custom-1',name:'Маска',unit:'шт',price:100,pack:1,archived:false});config.templates.push({id:1,name:'Услуга',raw:{wTime:2}});const payload={app:'master-calc',schemaVersion:3,history:[receipt(1)],settings:JSON.parse(a.run('JSON.stringify(getSettings())')),config};a.run('globalThis.importInput={files:[],value:"file"}');a.run('importInput').files.push({size:100,text:async()=>JSON.stringify(payload)});await a.run('importBackup(importInput)');assert.equal(a.run('getConfig().catalog.length'),8);assert.equal(a.run('getConfig().templates.length'),1);payload.schemaVersion=2;delete payload.config;await a.run('importBackup(importInput)');assert.equal(a.run('getConfig().catalog.length'),8);});
test('offline save never attempts submission and records local status',()=>{const a=app();a.run('navigator.onLine=false;calculate();saveData()');assert.equal(a.submitted,0);assert.equal(JSON.parse(a.store.get('master_calc_palette_history_final'))[0].cloudStatus,'local-only');assert.ok(a.element('save-result').innerText.includes('Без сети'));});
test('online save records unconfirmed attempt, not confirmed cloud receipt',()=>{const a=app();a.run('navigator.onLine=true;calculate();saveData()');assert.equal(a.submitted,1);assert.equal(JSON.parse(a.store.get('master_calc_palette_history_final'))[0].cloudStatus,'attempted-unconfirmed');});
test('multiple expenses and configurable deductions preserve financial identity',()=>{const a=app();a.run('extraExpenses=[{id:1,name:"Транспорт",amount:100},{id:2,name:"Доставка",amount:50}]');a.element('extra-value-1').value=100;a.element('extra-value-2').value=50;a.element('tax-percent').value=4;a.element('fee-percent').value=2;a.run('calculate()');assert.equal(a.run('currentCalc.total'),4420);assert.equal(a.run('currentCalc.profit'),3384.8);assert.equal(a.run('currentCalc.moneyCents.total-currentCalc.moneyCents.exp'),a.run('currentCalc.moneyCents.profit'));a.element('cover-deductions').checked=true;a.run('calculate()');assert.ok(a.run('currentCalc.profit')>=3650);});
test('invalid raw expense IDs cannot enter imported templates or receipts',()=>{const a=app();assert.equal(a.run('validRaw({extraExpenses:[{id:"1);alert(1)",name:"Bad",amount:1}]})'),false);assert.equal(a.run('validReceipt({id:1,date:"today",name:"name",recipe:"",total:1,exp:1,profit:0,workTime:1,raw:{customQuantities:{"bad/key":"1"}}})'),false);assert.equal(a.run('validRaw({wTime:Infinity})'),false);});
test('delete and restore preserve check contents and totals',()=>{const a=app();const entry=receipt(1);a.store.set('master_calc_palette_history_final',JSON.stringify([entry]));a.run('deleteItem(1)');assert.equal(JSON.parse(a.store.get('master_calc_palette_history_final')).length,0);assert.deepEqual(JSON.parse(a.store.get('master_calc_palette_deleted_v2')),[entry]);a.run('restoreDeleted()');assert.deepEqual(JSON.parse(a.store.get('master_calc_palette_history_final')),[entry]);assert.equal(a.store.has('master_calc_palette_deleted_v2'),false);});
test('CSV selection follows date period and client search, formula names escaped',()=>{const a=app();a.store.set('master_calc_palette_history_final',JSON.stringify([receipt(1,{name:'Нужный',date:'01.10.2026'}),receipt(2,{name:'Другой',date:'01.10.2026'}),receipt(3,{name:'Нужный',date:'01.11.2026'})]));a.element('history-from').value='2026-10-01';a.element('history-to').value='2026-10-31';a.element('search-history').value='нужный';assert.equal(a.run('selectedHistory().length'),1);assert.equal(a.run('csvText("=1+1")'),"'=1+1");assert.equal(a.run('csvText("ordinary")'),'ordinary');});

test('blank material fields count as zero while blank hours remain invalid',()=>{const a=app();a.element('m-estel').value='';assert.equal(a.run('calculate()'),true);assert.equal(a.run('currentCalc.raw.gE'),0);a.element('work-time').value='';assert.equal(a.run('calculate()'),false);});
test('legacy fixed rent receipt repeats under explicit hourly alternative',()=>{const a=app();a.run('applyRaw({wTime:1,rTime:2,cCount:1,rType:"prem",rentMode:"fixed",rentFixed:100})');a.run('calculate()');assert.equal(a.run('currentCalc.breakdown.rent'),840);assert.equal(a.run('currentCalc.raw.rentMode'),'hourly');});


test('palette never changes original site storage on a shared origin',()=>{const a=app();const oldHistory=JSON.stringify([receipt(12)]),oldSettings=JSON.stringify({hour:1234});a.store.set('master_calc_history_final',oldHistory);a.store.set('master_calc_settings_final',oldSettings);a.store.set('m_history',oldHistory);a.run('migrateOldData();calculate();saveData()');assert.equal(a.store.get('master_calc_history_final'),oldHistory);assert.equal(a.store.get('master_calc_settings_final'),oldSettings);assert.equal(a.store.get('m_history'),oldHistory);assert.equal(JSON.parse(a.store.get('master_calc_palette_history_final')).length,1);});


test('incomplete browser number input is invalid even when empty materials are allowed',()=>{const a=app();a.element('m-estel').value='';a.element('m-estel').validity={badInput:true};assert.equal(a.run('calculate(false,true)'),false);assert.equal(a.run('currentCalc'),null);assert.equal(a.element('save-receipt').disabled,true);a.element('m-estel').validity.badInput=false;assert.equal(a.run('calculate(false,true)'),true);assert.equal(a.run('currentCalc.raw.gE'),0);});


const DRAFT_KEY='master_calc_palette_draft_v1';
test('untouched startup and pagehide do not create a draft',()=>{const a=app();a.boot();a.pagehide();assert.equal(a.store.has(DRAFT_KEY),false);assert.equal(a.element('draft-banner').hidden,true);assert.equal(a.run('protectCurrentCalculation()'),true);});
test('draft restores exposed raw invalid strings, blanks, client, extras, selections and context',()=>{
 const a=app();a.boot();a.run('globalThis.config=getConfig();config.catalog.push({id:"custom-1",name:"Маска",unit:"шт",price:100,pack:1,archived:false});config.templates.push({id:42,name:"Черновик",raw:{wTime:1}});persistConfig(config);chooseMaterial("custom-1");addExtraExpense()');
 const extraID=a.run('extraExpenses[0].id');a.element('calc-client-name').value='  Анна <&>  ';a.element('work-time').value='';a.element('m-estel').value='-';a.element('quantity-custom-1').value='1e';a.element('extra-label-'+extraID).value='Дорога <&>';a.element('extra-value-'+extraID).value='';a.element('tax-percent').value='4.50';a.element('cover-deductions').checked=true;a.element('extras-panel').open=true;a.element('service-template').value='42';a.run('persistDraft()');
 const b=app({store:a.store});b.boot();assert.equal(b.element('calc-client-name').value,'  Анна <&>  ');assert.equal(b.element('work-time').value,'');assert.equal(b.element('m-estel').value,'-');assert.equal(b.element('quantity-custom-1').value,'1e');assert.equal(b.element('extra-label-'+extraID).value,'Дорога <&>');assert.equal(b.element('extra-value-'+extraID).value,'');assert.equal(b.element('tax-percent').value,'4.50');assert.equal(b.element('cover-deductions').checked,true);assert.equal(b.element('extras-panel').open,true);assert.equal(b.element('service-template').value,'42');assert.equal(b.run('currentCalc'),null);assert.equal(b.element('save-receipt').disabled,true);assert.equal(b.element('draft-banner').hidden,false);assert.match(b.element('draft-message').innerText,/Восстановлен/);
});
test('input persists before calculation debounce and pagehide flushes latest fields',()=>{const a=app();a.boot();a.element('calc-client-name').value='Первая';a.input('calc-client-name');assert.equal(JSON.parse(a.store.get(DRAFT_KEY)).fields['calc-client-name'],'Первая');a.element('calc-client-name').value='Последняя';a.pagehide();const b=app({store:a.store});b.boot();assert.equal(b.element('calc-client-name').value,'Последняя');});
test('browser badInput material stays invalid after reload until a genuine field input',()=>{const a=app();a.boot();a.element('m-estel').value='';a.element('m-estel').validity.badInput=true;a.input('m-estel');const b=app({store:a.store});b.boot();assert.equal(b.run('calculate(false,true)'),false);assert.equal(b.element('m-estel').getAttribute('aria-invalid'),'true');b.element('work-time').value='2';b.input('work-time');b.flush();assert.equal(b.run('currentCalc'),null);b.element('m-estel').value='10';b.input('m-estel');b.flush();assert.equal(b.run('currentCalc.materialLines[0].quantity'),10);});
test('new calculation guards existing draft and resets every calculation field and pending timer',()=>{const a=app();a.boot();a.element('calc-client-name').value='Анна';a.element('m-estel').value='60';a.element('work-mode').value='fixed';a.element('cover-deductions').checked=true;a.run('addExtraExpense();scheduleCalculation()');a.element('extras-panel').open=true;a.element('template-name').value='Окрашивание';a.confirm(false);assert.equal(a.run('startNewCalculation()'),false);assert.equal(a.element('calc-client-name').value,'Анна');a.confirm(true);assert.equal(a.run('startNewCalculation()'),true);a.flush();a.pagehide();assert.equal(a.element('calc-client-name').value,'');assert.equal(a.element('m-estel').value,'');assert.equal(a.element('work-mode').value,'hourly');assert.equal(a.element('cover-deductions').checked,false);assert.equal(a.run('extraExpenses.length'),0);assert.equal(a.element('extras-panel').open,false);assert.equal(a.element('template-name').value,'');assert.equal(a.store.has(DRAFT_KEY),false);const b=app({store:a.store});b.boot();assert.equal(b.element('calc-client-name').value,'');});
test('successful receipt save clears draft and cannot resurrect old client after input/pagehide',()=>{const a=app();a.boot();a.element('calc-client-name').value='Анна';a.input('calc-client-name');a.flush();a.run('saveData();saveData()');a.pagehide();assert.equal(a.store.has(DRAFT_KEY),false);assert.equal(JSON.parse(a.store.get('master_calc_palette_history_final')).length,1);const b=app({store:a.store});b.boot();assert.equal(b.element('calc-client-name').value,'');assert.equal(b.element('draft-banner').hidden,true);});
test('failed receipt write retains recoverable draft and current client for retry',()=>{const a=app({failWriteKey:'master_calc_palette_history_final'});a.boot();a.element('calc-client-name').value='Анна';a.input('calc-client-name');a.flush();const draft=a.store.get(DRAFT_KEY);a.run('saveData()');assert.equal(a.store.get(DRAFT_KEY),draft);assert.equal(a.element('calc-client-name').value,'Анна');assert.ok(a.run('currentCalc'));assert.equal(a.submitted,0);assert.equal(a.store.has('master_calc_palette_history_final'),false);const b=app({store:a.store});b.boot();assert.equal(b.element('calc-client-name').value,'Анна');});
test('draft write failure leaves existing source intact and displays lasting honest warning',()=>{const a=app();a.boot();a.element('calc-client-name').value='Первая';a.input('calc-client-name');const draft=a.store.get(DRAFT_KEY);a.failWrites();a.element('calc-client-name').value='Последняя';a.input('calc-client-name');assert.equal(a.store.get(DRAFT_KEY),draft);assert.equal(a.element('draft-banner').hidden,false);assert.match(a.element('draft-message').innerText,/Не удалось сохранить черновик/);a.flush();assert.equal(a.element('draft-banner').hidden,false);});
test('corrupt and unsupported drafts preserve source until explicit new calculation',()=>{for(const source of ['broken','{"schemaVersion":99}']){const a=app();a.store.set(DRAFT_KEY,source);a.boot();assert.equal(a.store.get(DRAFT_KEY),source);assert.equal(a.element('draft-banner').hidden,false);assert.match(a.element('draft-message').innerText,/не восстановлен/);a.element('calc-client-name').value='Новое имя';a.input('calc-client-name');a.pagehide();assert.equal(a.store.get(DRAFT_KEY),source);assert.equal(a.run('startNewCalculation()'),true);assert.equal(a.store.has(DRAFT_KEY),false);}});
test('missing selected draft material preserves source and restores nothing partially',()=>{const a=app();a.boot();a.run('globalThis.config=getConfig();config.catalog.push({id:"custom-1",name:"Маска",unit:"шт",price:100,pack:1,archived:false});persistConfig(config);chooseMaterial("custom-1")');a.element('calc-client-name').value='Анна';a.run('persistDraft()');a.store.delete('master_calc_palette_config_v3');const original=a.store.get(DRAFT_KEY),b=app({store:a.store});b.boot();assert.equal(b.element('calc-client-name').value,'');assert.equal(b.element('draft-banner').hidden,false);b.pagehide();assert.equal(b.store.get(DRAFT_KEY),original);});
test('new calculation refuses to discard form when draft removal fails',()=>{const a=app();a.boot();a.element('calc-client-name').value='Анна';a.input('calc-client-name');a.failRemove();assert.equal(a.run('startNewCalculation()'),false);assert.equal(a.element('calc-client-name').value,'Анна');assert.ok(a.store.get(DRAFT_KEY));assert.equal(a.element('draft-banner').hidden,false);});
test('saved receipt prevents resurrection even when draft removal fails',()=>{const a=app();a.boot();a.element('calc-client-name').value='Анна';a.input('calc-client-name');a.flush();assert.ok(a.store.get(DRAFT_KEY));a.failRemove();a.run('saveData()');assert.equal(a.element('calc-client-name').value,'');const b=app({store:a.store});b.boot();assert.equal(b.element('calc-client-name').value,'');assert.equal(JSON.parse(b.store.get('master_calc_palette_history_final')).length,1);});
test('programmatic receipt, template and contact updates persist their current client',async()=>{const a=app();a.boot();a.store.set('master_calc_palette_history_final',JSON.stringify([receipt(1,{name:'Анна',raw:{wTime:2,rTime:0,cCount:0}})]));a.run('loadReceipt(1)');let b=app({store:a.store});b.boot();assert.equal(b.element('calc-client-name').value,'Анна');assert.equal(b.element('work-time').value,'2');a.run('globalThis.config=getConfig();config.templates.push({id:2,name:"Стрижка",raw:{wTime:3}});persistConfig(config)');a.element('service-template').value='2';a.run('applyTemplate()');b=app({store:a.store});b.boot();assert.equal(b.element('calc-client-name').value,'Анна');assert.equal(b.element('work-time').value,'3');a.run('navigator.contacts={select:async()=>[{name:["Елена"]}]}');await a.run('getContact()');b=app({store:a.store});b.boot();assert.equal(b.element('calc-client-name').value,'Елена');});
test('explicit material clear removes restored invalid markers and persists a valid draft',()=>{const a=app();a.boot();a.element('m-estel').validity.badInput=true;a.input('m-estel');const b=app({store:a.store});b.boot();assert.equal(b.run('currentCalc'),null);b.run('clearMaterials()');assert.ok(b.run('currentCalc'));const c=app({store:b.store});c.boot();assert.ok(c.run('currentCalc'));});
test('valid programmatic raw replacement clears old invalid markers before calculation',()=>{const a=app();a.boot();a.element('m-estel').validity.badInput=true;a.input('m-estel');const b=app({store:a.store});b.boot();assert.equal(b.run('currentCalc'),null);b.run('applyRaw({wTime:2,gE:10});persistDraft()');assert.equal(b.run('calculate(false,true)'),true);assert.equal(b.run('currentCalc.materialLines[0].quantity'),10);});
test('dynamic rerender retains incomplete material and expense validity until edited or removed',()=>{const a=app();a.boot();a.run('globalThis.config=getConfig();config.catalog.push({id:"custom-1",name:"Маска",unit:"шт",price:100,pack:1,archived:false});persistConfig(config);chooseMaterial("custom-1");addExtraExpense()');const expense=a.run('extraExpenses[0].id');a.element('quantity-custom-1').validity.badInput=true;a.input('quantity-custom-1');a.element('extra-value-'+expense).value='';a.element('extra-value-'+expense).validity.badInput=true;a.input('extra-value-'+expense);a.run('refreshCatalog();addExtraExpense()');const b=app({store:a.store});b.boot();assert.equal(b.element('quantity-custom-1').getAttribute('aria-invalid'),'true');assert.equal(b.element('extra-value-'+expense).getAttribute('aria-invalid'),'true');assert.equal(b.run('calculate(false,true)'),false);b.run('removeExtraExpense('+expense+');removeMaterial("custom-1")');assert.equal(b.run('calculate(false,true)'),true);});
test('unreadable draft storage blocks overwrite and shows persistent warning',()=>{const a=app({failReadKey:DRAFT_KEY});a.store.set(DRAFT_KEY,'original');a.boot();assert.equal(a.element('draft-banner').hidden,false);assert.match(a.element('draft-message').innerText,/не восстановлен/);a.element('calc-client-name').value='Новое';a.input('calc-client-name');a.pagehide();assert.equal(a.store.get(DRAFT_KEY),'original');});
test('retired draft stays retired when saved receipt has moved to deleted history',()=>{const a=app();a.boot();a.element('calc-client-name').value='Анна';a.input('calc-client-name');a.flush();a.failRemove();a.run('saveData()');a.run('deleteItem(readHistory()[0].id)');const b=app({store:a.store});b.boot();assert.equal(b.element('calc-client-name').value,'');assert.equal(b.run('readDeleted().length'),1);});
test('saving a new receipt does not erase an unrestorable draft source',()=>{const a=app();a.store.set(DRAFT_KEY,'broken');a.boot();a.element('calc-client-name').value='Новая услуга';a.input('calc-client-name');a.flush();a.run('saveData()');assert.equal(JSON.parse(a.store.get('master_calc_palette_history_final'))[0].name,'Новая услуга');assert.equal(a.element('calc-client-name').value,'');assert.equal(a.store.get(DRAFT_KEY),'broken');a.pagehide();assert.equal(a.store.get(DRAFT_KEY),'broken');assert.equal(a.element('draft-banner').hidden,false);});
test('successful import persists final composition and retained client context before pagehide',async()=>{for(const version of [2,3]){
 const a=app();a.boot();a.run('globalThis.config=getConfig();config.catalog.push({id:"custom-1",name:"Маска",unit:"шт",price:100,pack:1,archived:false});persistConfig(config);chooseMaterial("custom-1")');a.element('quantity-custom-1').value='2';a.input('quantity-custom-1');a.element('calc-client-name').value='Анна';a.element('work-time').value='3';a.element('templates-panel').open=true;a.element('template-name').value='Моя услуга';a.input('work-time');
 const payload={app:'master-calc',schemaVersion:version,history:[receipt(1)],settings:{...JSON.parse(a.run('JSON.stringify(getSettings())')),hour:1000}};if(version===3)payload.config={catalog:JSON.parse(a.run('JSON.stringify(getConfig().catalog.filter(i=>i.id!=="custom-1"))')),templates:[]};a.run('globalThis.importInput={files:[],value:"file"}');a.run('importInput').files.push({size:100,text:async()=>JSON.stringify(payload)});await a.run('importBackup(importInput)');
 assert.equal(a.element('work-time').value,'1');const stored=JSON.parse(a.store.get(DRAFT_KEY));assert.equal(stored.fields['work-time'],'1');assert.equal(stored.fields['calc-client-name'],'Анна');assert.deepEqual(stored.customQuantities,{});assert.equal(stored.context.templatesOpen,true);assert.equal(stored.context.templateName,'Моя услуга');const b=app({store:a.store});b.boot();assert.equal(b.element('calc-client-name').value,'Анна');assert.equal(b.element('work-time').value,'1');assert.equal(b.run('Object.keys(customQuantities).length'),0);assert.equal(b.element('templates-panel').open,true);assert.equal(b.element('template-name').value,'Моя услуга');assert.equal(b.run('currentCalc.total'),1770);
}});
test('successful import preserves blocked draft source and its warning',async()=>{const a=app();a.store.set(DRAFT_KEY,'broken');a.boot();a.element('calc-client-name').value='Анна';a.input('calc-client-name');const payload={app:'master-calc',schemaVersion:2,history:[receipt(1)],settings:JSON.parse(a.run('JSON.stringify(getSettings())'))};a.run('globalThis.importInput={files:[],value:"file"}');a.run('importInput').files.push({size:100,text:async()=>JSON.stringify(payload)});await a.run('importBackup(importInput)');assert.equal(a.run('readHistory().length'),1);assert.equal(a.store.get(DRAFT_KEY),'broken');assert.equal(a.element('draft-banner').hidden,false);assert.match(a.element('draft-message').innerText,/не восстановлен/);});

test('settings pin and order include custom materials and survive reload',()=>{const a=app();a.boot();a.run('globalThis.config=getConfig();config.catalog.push({id:"custom-1",name:"Маска",unit:"шт",price:100,pack:1,archived:false});persistConfig(config);togglePaletteFavorite("custom-1");movePaletteMaterial("custom-1",-1)');assert.equal(a.run('palettePreferences().favorites.includes("custom-1")'),true);assert.equal(a.run('palettePreferences().order[6]'),'custom-1');assert.match(a.element('custom-materials').innerHTML,/quantity-custom-1/);assert.equal(a.store.has(DRAFT_KEY),false);const b=app({store:a.store});b.boot();assert.equal(b.run('palettePreferences().order[6]'),'custom-1');assert.equal(b.run('palettePreferences().favorites.includes("custom-1")'),true);assert.equal(b.element('row-estel').style.order,0);});
test('active unpinned and archived materials remain visible and charged',()=>{const a=app();a.boot();a.element('m-estel').value='10';a.input('m-estel');a.run('togglePaletteFavorite("estel");archiveCatalogItem("estel");calculate(false,true)');assert.equal(a.element('row-estel').hidden,false);assert.equal(a.run('currentCalc.breakdown.matCost'),77.5);a.run('removeMaterial("estel")');assert.equal(a.element('row-estel').hidden,true);a.run('globalThis.config=getConfig();config.catalog.push({id:"custom-1",name:"Маска",unit:"шт",price:100,pack:1,archived:false});persistConfig(config);chooseMaterial("custom-1")');a.element('quantity-custom-1').value='2';a.input('quantity-custom-1');a.run('archiveCatalogItem("custom-1");calculate(false,true)');assert.match(a.element('custom-materials').innerHTML,/quantity-custom-1/);assert.equal(a.run('currentCalc.breakdown.matCost'),200);});
test('hours and minutes presentation preserves exact legacy durations with decimal fallback',()=>{const a=app();a.boot();a.run('applyRaw({wTime:1.25,rTime:1.3333333});setDurationMode("minutes")');assert.equal(a.element('work-minutes').value,'15');assert.equal(a.element('work-duration-parts').hidden,false);assert.equal(a.element('rent-duration-parts').hidden,true);assert.equal(a.element('rent-time').value,'1.3333333');a.run('calculate(false,true);persistDraft()');assert.equal(a.run('currentCalc.raw.rTime'),1.3333333);const b=app({store:a.store});b.boot();assert.equal(b.element('rent-time').value,'1.3333333');assert.equal(b.element('duration-display').value,'minutes');assert.equal(b.run('currentCalc.raw.wTime'),1.25);b.element('work-hours').value='2';b.input('work-hours');b.flush();assert.equal(b.run('currentCalc.raw.wTime'),2.25);});
test('rent link is explicit and manual decimal or minute rent input unlinks',()=>{const a=app();a.boot();a.element('work-time').value='2';a.input('work-time');assert.equal(a.element('rent-time').value,'1');a.element('rent-link').checked=true;a.input('rent-link');assert.equal(a.element('rent-time').value,'2');a.element('work-time').value='3.5';a.input('work-time');assert.equal(a.element('rent-time').value,'3.5');a.run('persistDraft()');const b=app({store:a.store});b.boot();assert.equal(b.element('rent-link').checked,true);b.element('rent-time').value='2.75';b.input('rent-time');assert.equal(b.element('rent-link').checked,false);b.run('setDurationMode("minutes")');b.element('rent-link').checked=true;b.input('rent-link');b.element('rent-minutes').value='20';b.input('rent-minutes');assert.equal(b.element('rent-link').checked,false);b.flush();assert.equal(b.run('currentCalc.raw.rTime'),3+20/60);});
test('partial minute input stays invalid and recoverable and reset removes duration link',()=>{const a=app();a.boot();a.run('setDurationMode("minutes")');a.element('work-minutes').value='';a.input('work-minutes');a.flush();assert.equal(a.run('currentCalc'),null);const b=app({store:a.store});b.boot();assert.equal(b.element('work-minutes').value,'');assert.equal(b.run('currentCalc'),null);b.run('startNewCalculation()');assert.equal(b.element('duration-display').value,'decimal');assert.equal(b.element('rent-link').checked,false);assert.equal(b.store.has(DRAFT_KEY),false);});
test('legacy draft without duration and palette additions remains loadable',()=>{const a=app();a.boot();a.element('work-time').value='1.3333333333333333';a.input('work-time');const d=JSON.parse(a.store.get(DRAFT_KEY));delete d.duration;delete d.selectedMaterials;a.store.set(DRAFT_KEY,JSON.stringify(d));const b=app({store:a.store});b.boot();assert.equal(b.element('work-time').value,'1.3333333333333333');assert.equal(b.run('currentCalc.raw.wTime'),1.3333333333333333);assert.match(b.element('draft-message').innerText,/Восстановлен/);});

test('invalid minute range is preserved through draft reload without becoming valid',()=>{const a=app();a.boot();a.run('setDurationMode("minutes")');a.element('work-minutes').value='60';a.input('work-minutes');a.flush();assert.equal(a.run('currentCalc'),null);const b=app({store:a.store});b.boot();assert.equal(b.element('work-minutes').value,'60');assert.equal(b.run('currentCalc'),null);b.element('work-minutes').value='30';b.input('work-minutes');b.flush();assert.equal(b.run('currentCalc.raw.wTime'),1.5);});
test('unpinned active custom material survives reload with exact quantity',()=>{const a=app();a.boot();a.run('globalThis.config=getConfig();config.catalog.push({id:"custom-1",name:"Тоник",unit:"мл",price:100,pack:100,archived:false});persistConfig(config);togglePaletteFavorite("custom-1")');a.element('quantity-custom-1').value='12.345';a.input('quantity-custom-1');a.run('togglePaletteFavorite("custom-1");persistDraft()');const b=app({store:a.store});b.boot();assert.equal(b.element('quantity-custom-1').value,'12.345');assert.equal(b.run('currentCalc.materialLines[0].quantity'),12.345);assert.equal(b.run('currentCalc.breakdown.matCost'),12.35);});
test('draft duration cannot inject unrelated input IDs during recovery',()=>{const a=app();a.boot();a.element('calc-client-name').value='Анна';a.input('calc-client-name');const d=JSON.parse(a.store.get(DRAFT_KEY));d.duration.parts['calc-client-name']='Подмена';a.run('globalThis.malformedDraft='+JSON.stringify(d));assert.equal(a.run('validDraft(malformedDraft)'),false);});
test('linking valid work replaces recovered invalid rent parts and clears errors',()=>{const a=app();a.boot();a.run('setDurationMode("minutes")');a.element('rent-minutes').value='';a.element('rent-minutes').validity.badInput=true;a.input('rent-minutes');a.flush();assert.equal(a.run('currentCalc'),null);const b=app({store:a.store});b.boot();assert.equal(b.run('draftInvalidFields.has("rent-minutes")'),true);b.element('rent-link').checked=true;b.input('rent-link');b.flush();assert.ok(b.run('currentCalc'));assert.equal(b.element('rent-minutes').value,'0');assert.equal(b.element('rent-minutes').getAttribute('aria-invalid'),'false');assert.equal(b.run('draftInvalidFields.has("rent-minutes")'),false);const c=app({store:b.store});c.boot();assert.equal(c.element('rent-link').checked,true);assert.equal(c.run('currentCalc.raw.rTime'),1);});
test('corrected decimal time clears replaced invalid minute markers',()=>{const a=app();a.boot();a.run('setDurationMode("minutes")');a.element('work-minutes').value='';a.element('work-minutes').validity.badInput=true;a.input('work-minutes');const b=app({store:a.store});b.boot();b.run('setDurationMode("decimal")');b.element('work-time').value='1.5';b.input('work-time');b.run('setDurationMode("minutes")');b.flush();assert.equal(b.run('currentCalc.raw.wTime'),1.5);assert.equal(b.run('draftInvalidFields.has("work-minutes")'),false);assert.equal(b.element('work-minutes').getAttribute('aria-invalid'),'false');});
test('linking invalid work cannot clear its bad input state or make the calculation valid',()=>{const a=app();a.boot();a.run('setDurationMode("minutes")');a.element('work-minutes').value='';a.element('work-minutes').validity.badInput=true;a.input('work-minutes');a.element('rent-link').checked=true;a.input('rent-link');a.flush();assert.equal(a.run('currentCalc'),null);assert.equal(a.run('draftInvalidFields.has("work-minutes")'),true);const b=app({store:a.store});b.boot();assert.equal(b.run('currentCalc'),null);assert.equal(b.run('draftInvalidFields.has("work-minutes")'),true);b.element('work-minutes').value='15';b.input('work-minutes');b.flush();assert.equal(b.run('currentCalc.raw.wTime'),1.25);assert.equal(b.run('currentCalc.raw.rTime'),1.25);});

// Task 3: local visit history, read-only viewing and honest backup controls.
test('local suggestions retain dated visits with duplicate names and selection only changes name',()=>{const a=app();a.boot();a.store.set('master_calc_palette_history_final',JSON.stringify([receipt(2,{name:'Анна',date:'06.10.2026',raw:{wTime:9}}),receipt(1,{name:'Анна',date:'05.10.2026',raw:{wTime:8}})]));a.element('work-time').value='2.25';a.element('m-estel').value='11.5';a.input('work-time');a.element('calc-client-name').value='Ан';a.input('calc-client-name');assert.match(a.element('client-suggestions').innerHTML,/06.10.2026/);assert.match(a.element('client-suggestions').innerHTML,/05.10.2026/);assert.equal(a.run('clientSuggestions("Ан").length'),2);a.run('selectClientVisit(1)');assert.equal(a.element('calc-client-name').value,'Анна');assert.equal(a.element('work-time').value,'2.25');assert.equal(a.element('m-estel').value,'11.5');const b=app({store:a.store});b.boot();assert.equal(b.element('calc-client-name').value,'Анна');assert.equal(b.element('work-time').value,'2.25');assert.equal(a.submitted,0);});
test('receipt viewing uses saved values without touching raw draft or current calculation',()=>{const a=app();a.boot();a.element('calc-client-name').value='Черновик';a.element('work-time').value='3';a.input('work-time');a.flush();a.store.set('master_calc_palette_history_final',JSON.stringify([receipt(1,{name:'<Анна>',total:100,profit:70,exp:30,raw:{wTime:9},materialLines:[{name:'Старое имя',quantity:2,unit:'г',unitPrice:5,cost:10}]})]));const before=a.store.get('master_calc_palette_draft_v1'),calc=a.run('JSON.stringify(currentCalc)');assert.equal(a.run('openReceipt(1)'),true);assert.equal(a.element('receipt-dialog').open,true);assert.match(a.element('receipt-content').innerHTML,/100 ₽/);assert.match(a.element('receipt-content').innerHTML,/Старое имя/);assert.match(a.element('receipt-content').innerHTML,/&lt;Анна&gt;/);assert.equal(a.store.get('master_calc_palette_draft_v1'),before);assert.equal(a.run('JSON.stringify(currentCalc)'),calc);assert.equal(a.submitted,0);});
test('repeat and template replacement cancellation preserves populated raw draft',()=>{for(const action of ['loadReceipt(1)','applyTemplate()']){const a=app();a.boot();a.store.set('master_calc_palette_history_final',JSON.stringify([receipt(1,{name:'Другой',raw:{wTime:8}})]));a.run('const c=getConfig();c.templates.push({id:1,name:"Шаблон",raw:{wTime:7}});persistConfig(c)');a.element('service-template').value='1';a.element('calc-client-name').value='Мой';a.element('work-time').value='';a.input('work-time');const before=a.store.get('master_calc_palette_draft_v1');a.confirm(false);a.run(action);assert.equal(a.element('calc-client-name').value,'Мой');assert.equal(a.element('work-time').value,'');assert.equal(a.store.get('master_calc_palette_draft_v1'),before);assert.equal(a.confirmations.length,1);a.confirm(true);a.run(action);assert.equal(a.element('work-time').value,action.startsWith('load')?'8':'7');}});
test('repeat is a new calculation using current tariffs and leaving historical receipt intact',()=>{const a=app();const original=JSON.stringify([receipt(1,{total:123,raw:{wTime:2,rTime:0,cCount:0}})]);a.store.set('master_calc_palette_history_final',original);a.store.set('master_calc_palette_settings_final',JSON.stringify({hour:1000}));a.run('loadReceipt(1)');assert.equal(a.run('currentCalc.total'),2000);assert.equal(a.store.get('master_calc_palette_history_final'),original);assert.equal(a.submitted,0);});
test('client summary copy omits private income costs rates and recipe',async()=>{const a=app();a.element('calc-client-name').value='Анна';a.run('calculate();globalThis.copied="";navigator.clipboard={writeText:async text=>{copied=text}}');assert.equal(await a.run('copyClientSummary()'),true);const text=a.run('copied');assert.match(text,/Анна/);assert.match(text,/4270 ₽/);assert.doesNotMatch(text,/Доход|расход|620|3650|Estel|тариф|Материал/);assert.equal(a.submitted,0);});
test('backup export records honest last download state and changed receipt reminder without blocking',()=>{const a=app();a.boot();a.store.set('master_calc_palette_history_final',JSON.stringify([receipt(1)]));a.run('refreshBackupStatus()');assert.match(a.element('backup-reminder').innerText,/1/);a.run('exportBackup()');assert.ok(a.store.get('master_calc_palette_backup_state_v1'));assert.match(a.element('backup-status').innerText,/Скачивание/);assert.equal(a.element('backup-reminder').hidden,true);a.store.set('master_calc_palette_history_final',JSON.stringify([receipt(1,{total:999}),receipt(2)]));a.run('refreshBackupStatus()');assert.match(a.element('backup-reminder').innerText,/2/);assert.equal(a.confirmations.length,0);a.run('calculate();saveData()');assert.equal(a.submitted,1);});
test('import has one clear preview and cancel leaves history config settings and draft untouched',async()=>{const a=app();a.boot();a.element('calc-client-name').value='Текущий';a.element('work-time').value='3';a.input('work-time');a.store.set('master_calc_palette_history_final',JSON.stringify([receipt(1)]));const before=JSON.stringify([...a.store]);const payload={app:'master-calc',schemaVersion:3,history:[receipt(1),receipt(2)],settings:JSON.parse(a.run('JSON.stringify(getSettings())')),config:JSON.parse(a.run('JSON.stringify(getConfig())'))};a.run('globalThis.importInput={files:[],value:"file"}');a.run('importInput').files.push({size:100,text:async()=>JSON.stringify(payload)});a.confirm(false);await a.run('importBackup(importInput)');assert.equal(JSON.stringify([...a.store]),before);assert.equal(a.confirmations.length,1);assert.match(a.confirmations[0],/Предпросмотр/);assert.match(a.confirmations[0],/Новых чеков: 1/);assert.match(a.confirmations[0],/Текущий расчёт/);assert.equal(a.run('importInput.value'),'');});
test('optional Google preference defaults to prior sending and opt-out is backed up with config',()=>{const a=app();assert.equal(a.run('googleSendEnabled()'),true);a.boot();a.element('google-send').checked=false;a.run('saveGooglePreference();calculate();saveData()');assert.equal(a.submitted,0);assert.equal(a.run('getConfig().googleSend'),false);assert.match(a.element('save-status').innerText,/отключена/);const b=app({store:a.store});b.boot();assert.equal(b.element('google-send').checked,false);assert.equal(b.run('validConfig({...getConfig(),googleSend:"false"})'),false);assert.equal(b.run('validConfig({...getConfig(),googleSend:true})'),true);});
test('old v3 backup without Google preference preserves an existing opt-out',async()=>{const a=app();a.boot();const payload={app:'master-calc',schemaVersion:3,history:[],settings:JSON.parse(a.run('JSON.stringify(getSettings())')),config:JSON.parse(a.run('JSON.stringify(getConfig())'))};a.element('google-send').checked=false;a.run('saveGooglePreference()');a.run('globalThis.importInput={files:[],value:"file"}');a.run('importInput').files.push({size:100,text:async()=>JSON.stringify(payload)});await a.run('importBackup(importInput)');assert.equal(a.run('googleSendEnabled()'),false);assert.equal(a.element('google-send').checked,false);assert.match(a.confirmations[0],/Настройка Google останется текущей/);});
test('template on otherwise untouched form needs no replacement confirmation',()=>{const a=app();a.boot();a.run('const c=getConfig();c.templates.push({id:1,name:"Шаблон",raw:{wTime:2}});persistConfig(c)');a.element('service-template').value='1';a.confirm(false);a.run('applyTemplate()');assert.equal(a.element('work-time').value,'2');assert.equal(a.confirmations.length,0);});
test('copy fallback exposes only client text for manual selection without transmission',async()=>{const a=app();a.run('calculate()');assert.equal(await a.run('copyClientSummary()'),false);assert.equal(a.element('client-copy-dialog').open,true);assert.match(a.element('client-copy-text').value,/4270 ₽/);assert.doesNotMatch(a.element('client-copy-text').value,/3650|620|Доход|расход/);assert.equal(a.submitted,0);});
test('new calculation clears suggestions from the previous client',()=>{const a=app();a.boot();a.store.set('master_calc_palette_history_final',JSON.stringify([receipt(1,{name:'Анна'})]));a.element('calc-client-name').value='Ан';a.input('calc-client-name');assert.equal(a.element('client-suggestions').hidden,false);a.run('startNewCalculation()');assert.equal(a.element('calc-client-name').value,'');assert.equal(a.element('client-suggestions').hidden,true);assert.equal(a.element('client-suggestions').innerHTML,'');});

// Task 4: immutable historical context, accounting and safe local corrections.
test('manual actual price stays pinned in draft and repeat/template reset it',()=>{const a=app();a.boot();a.element('actual-price-enabled').checked=true;a.element('actual-price').value='4600';a.element('tax-percent').value='6';a.element('fee-percent').value='2';a.input('actual-price');a.flush();assert.equal(a.run('currentCalc.profit'),3612);a.element('cover-deductions').checked=true;a.input('cover-deductions');a.flush();assert.equal(a.run('currentCalc.total'),4600);const b=app({store:a.store});b.boot();assert.equal(b.run('currentCalc.total'),4600);b.run('saveData()');const h=JSON.parse(b.store.get('master_calc_palette_history_final'));b.run(`loadReceipt(${h[0].id})`);assert.equal(b.element('actual-price-enabled').checked,false);b.element('template-name').value='Тест';b.run('saveTemplate()');const t=JSON.parse(b.store.get('master_calc_palette_config_v3')).templates[0];assert.equal(t.raw.actualPrice,undefined);});
test('historical edit preserves all original rates catalog ID date and revisions without send',()=>{const a=app();a.boot();a.element('m-estel').value='10';a.run('calculate();saveData()');const original=JSON.parse(a.store.get('master_calc_palette_history_final'))[0];assert.equal(original.catalogSnapshot.length,7);a.store.set('master_calc_palette_settings_final',JSON.stringify({hour:9000,pEstel:100}));a.run(`startReceiptEdit(${original.id})`);a.element('m-estel').value='20';a.run('calculate()');assert.equal(a.run('currentCalc.materialLines[0].unitPrice'),7.75);assert.equal(a.run('currentCalc.rates.hour'),3500);a.run('saveData()');const revised=JSON.parse(a.store.get('master_calc_palette_history_final'))[0];assert.equal(revised.id,original.id);assert.equal(revised.date,original.date);assert.equal(revised.createdAt,original.createdAt);assert.equal(revised.revisions.length,1);assert.deepEqual(revised.revisions[0],original);assert.equal(a.submitted,1);a.run(`undoReceipt(${original.id},${JSON.stringify(JSON.stringify(revised))})`);const restored=JSON.parse(a.store.get('master_calc_palette_history_final'))[0];assert.equal(restored.total,original.total);assert.equal(restored.revisions.length,2);assert.ok(restored.revisions.every(i=>!i.revisions));assert.equal(a.submitted,1);});
test('edit cancel restores exact prior draft even after reload and current catalog changes',()=>{const a=app();a.boot();a.run('calculate();saveData()');const id=JSON.parse(a.store.get('master_calc_palette_history_final'))[0].id;a.element('calc-client-name').value='Мой черновик';a.element('work-time').value='';a.input('work-time');const prior=a.store.get(DRAFT_KEY);a.run(`startReceiptEdit(${id})`);a.element('m-estel').value='12';a.input('m-estel');a.store.set('master_calc_palette_settings_final',JSON.stringify({hour:9000}));const b=app({store:a.store});b.boot();assert.ok(b.run('editSession'));assert.equal(b.run('currentCalc.rates.hour'),3500);b.run('cancelReceiptEdit()');assert.equal(b.element('calc-client-name').value,'Мой черновик');assert.equal(b.element('work-time').value,'');assert.deepEqual(JSON.parse(b.store.get(DRAFT_KEY)),JSON.parse(prior));});
test('concurrent edit and undo reject without writes',()=>{const a=app();a.boot();a.run('calculate();saveData()');let saved=JSON.parse(a.store.get('master_calc_palette_history_final'))[0];a.run(`startReceiptEdit(${saved.id})`);saved.name='Другая вкладка';const concurrent=JSON.stringify([saved]);a.store.set('master_calc_palette_history_final',concurrent);a.run('saveData()');assert.equal(a.store.get('master_calc_palette_history_final'),concurrent);assert.ok(a.run('editSession'));a.run(`undoReceipt(${saved.id},"obsolete")`);assert.equal(a.store.get('master_calc_palette_history_final'),concurrent);});
test('legacy snapshots restrict materials and missing snapshots explicitly disable editing',()=>{const a=app();a.boot();a.store.set('master_calc_palette_history_final',JSON.stringify([receipt(1,{raw:{wTime:1,gE:10},rates:JSON.parse(a.run('JSON.stringify(getSettings())')),materialLines:[{id:'estel',name:'Старый Estel',unit:'г',quantity:10,unitPrice:5,cost:50}]}),receipt(2,{raw:{wTime:1}})]));assert.equal(a.run('startReceiptEdit(2)'),false);a.run('openReceipt(2)');assert.match(a.element('receipt-actions').innerHTML,/недоступно/);assert.equal(a.run('startReceiptEdit(1)'),true);assert.equal(a.run('calculationConfig().catalog.length'),1);a.element('m-oxide').value='10';assert.equal(a.run('calculate()'),false);a.element('m-oxide').value='';a.element('m-estel').value='20';a.run('calculate()');assert.equal(a.run('currentCalc.materialLines[0].cost'),100);});
test('revision validation rejects recursion and malformed snapshots but accepts old raw backups',()=>{const a=app();const old=receipt(1,{raw:{wTime:1}});a.run('globalThis.old='+JSON.stringify(old));assert.equal(a.run('validReceipt(old)'),true);assert.equal(a.run('validReceipt({...old,revisions:[{...old,revisions:[old]}]})'),false);assert.equal(a.run('validReceipt({...old,catalogSnapshot:[{id:"bad",name:"x",unit:"г",unitPrice:-1}]})'),false);});
test('edit write failure and cancel failure retain source receipt session and prior draft',()=>{const a=app();a.boot();a.run('calculate();saveData()');const original=a.store.get('master_calc_palette_history_final'),id=JSON.parse(original)[0].id;a.element('calc-client-name').value='Черновик';a.input('calc-client-name');a.run(`startReceiptEdit(${id})`);a.element('work-time').value='2';a.input('work-time');a.flush();const editing=a.store.get(DRAFT_KEY);a.failWrites();a.run('saveData()');assert.equal(a.store.get('master_calc_palette_history_final'),original);assert.ok(a.run('editSession'));assert.equal(a.run('cancelReceiptEdit()'),false);assert.equal(a.store.get(DRAFT_KEY),editing);assert.ok(a.run('editSession'));a.allowWrites();a.run('cancelReceiptEdit()');assert.equal(a.element('calc-client-name').value,'Черновик');});
test('actual price invalid intermediate persists and negative income is visible and saveable',()=>{const a=app();a.boot();a.element('actual-price-enabled').checked=true;a.input('actual-price-enabled');a.element('actual-price').value='';a.input('actual-price');a.flush();assert.equal(a.run('currentCalc'),null);const b=app({store:a.store});b.boot();assert.equal(b.element('actual-price-enabled').checked,true);assert.equal(b.element('actual-price').value,'');assert.equal(b.run('currentCalc'),null);b.element('actual-price').value='100.01';b.input('actual-price');b.flush();assert.equal(b.element('negative-income').hidden,false);assert.equal(b.run('currentCalc.profit'),-519.99);b.run('saveData()');assert.equal(JSON.parse(b.store.get('master_calc_palette_history_final'))[0].total,100.01);});
test('new materials after a receipt cannot acquire invented historical prices',()=>{const a=app();a.boot();a.run('calculate();saveData()');const id=JSON.parse(a.store.get('master_calc_palette_history_final'))[0].id;a.run('const c=getConfig();c.catalog.push({id:"new-material",name:"Новый",unit:"г",price:999,pack:1,archived:false});persistConfig(c)');a.run(`startReceiptEdit(${id})`);assert.equal(a.run('calculationConfig().catalog.some(i=>i.id==="new-material")'),false);a.run('chooseMaterial("new-material")');assert.equal(a.run('Object.hasOwn(customQuantities,"new-material")'),false);});
test('text and number blur change cannot invalidate a valid first save or copy',()=>{const a=app();a.boot();a.element('calc-client-name').value='Анна';a.input('calc-client-name');a.flush();const before=a.run('currentCalc.total');a.element('calc').dispatch('change',a.element('calc-client-name'));assert.equal(a.run('currentCalc.total'),before);a.element('work-time').value='2';a.input('work-time');a.flush();a.element('calc').dispatch('change',a.element('work-time'));assert.equal(a.run('currentCalc.total'),7770);a.run('saveData()');assert.equal(JSON.parse(a.store.get('master_calc_palette_history_final')).length,1);});
test('select any flat revision including original after multiple edits, all retained',()=>{const a=app();a.boot();a.run('calculate();saveData()');const original=JSON.parse(a.store.get('master_calc_palette_history_final'))[0];for(const hours of [2,3,4]){a.run(`startReceiptEdit(${original.id})`);a.element('work-time').value=String(hours);a.run('calculate();saveData()');}let current=JSON.parse(a.store.get('master_calc_palette_history_final'))[0];assert.equal(current.revisions.length,3);assert.deepEqual(current.revisions[0],original);assert.ok(current.revisions.every(v=>v.revisions===undefined));a.run(`undoReceipt(${original.id},${JSON.stringify(JSON.stringify(current))},0)`);current=JSON.parse(a.store.get('master_calc_palette_history_final'))[0];assert.equal(current.total,original.total);assert.equal(current.revisions.length,4);assert.deepEqual(current.revisions[0],original);assert.equal(a.submitted,1);});
test('v3 backup round trip retains full original and revisions with additive actual fields',async()=>{const a=app();a.boot();a.run('calculate();saveData()');const id=JSON.parse(a.store.get('master_calc_palette_history_final'))[0].id;a.run(`startReceiptEdit(${id})`);a.element('actual-price-enabled').checked=true;a.element('actual-price').value='4600';a.run('calculate();saveData()');const history=JSON.parse(a.store.get('master_calc_palette_history_final'));const b=app();b.boot();const payload={app:'master-calc',schemaVersion:3,history,settings:JSON.parse(a.run('JSON.stringify(getSettings())')),config:JSON.parse(a.run('JSON.stringify(getConfig())'))};b.run('globalThis.importInput={files:[],value:"file"}');b.run('importInput').files.push({size:100,text:async()=>JSON.stringify(payload)});await b.run('importBackup(importInput)');assert.deepEqual(JSON.parse(b.store.get('master_calc_palette_history_final')),history);assert.equal(b.run('validReceipt({...readHistory()[0],revisions:[{...readHistory()[0].revisions[0],id:1}]})'),false);});
test('committed edit with failed draft cleanup recovers prior draft on reload without duplicate commit',()=>{class CountStore extends Map{writes=0;set(key,value){if(key==='master_calc_palette_history_final')this.writes++;return super.set(key,value)}}const options={store:new CountStore()},a=app(options);a.boot();a.run('calculate();saveData()');const id=JSON.parse(a.store.get('master_calc_palette_history_final'))[0].id;a.element('calc-client-name').value='Вернуть меня';a.input('calc-client-name');a.run(`startReceiptEdit(${id})`);a.element('work-time').value='2';a.input('work-time');a.flush();options.failWriteKey=DRAFT_KEY;a.store.writes=0;a.run('saveData()');assert.equal(a.store.writes,1);const revised=JSON.parse(a.store.get('master_calc_palette_history_final'))[0];assert.equal(revised.revisions.length,1);assert.ok(JSON.parse(a.store.get(DRAFT_KEY)).edit);const b=app({store:a.store});b.boot();assert.equal(b.run('editSession'),null);assert.equal(b.element('calc-client-name').value,'Вернуть меня');assert.equal(JSON.parse(b.store.get('master_calc_palette_history_final'))[0].revisions.length,1);});
test('applying imported template explicitly strips actual price override',()=>{const a=app();a.boot();a.run('const c=getConfig();c.templates.push({id:1,name:"Скидка",raw:{wTime:1,actualPrice:1}});persistConfig(c)');a.element('service-template').value='1';a.run('applyTemplate()');assert.equal(a.element('actual-price-enabled').checked,false);assert.equal(a.run('currentCalc.total'),4270);});

// Task 4 review I1: retain legacy material authority after removing active lines.
test('legacy built-in and custom historical prices survive zero/remove save, reload, re-add and backup',async()=>{for(const id of ['estel','custom-old'])for(const removal of ['zero','remove']){const a=app();a.boot();const builtin=id==='estel',field=builtin?'m-estel':'quantity-custom-old';const original=receipt(1,{rates:JSON.parse(a.run('JSON.stringify(getSettings())')),raw:{wTime:1,...(builtin?{gE:10}:{customQuantities:{'custom-old':10}})},materialLines:[{id,name:'Исторический материал',unit:'г',unitPrice:1.25,quantity:10,cost:12.5}]});a.store.set('master_calc_palette_history_final',JSON.stringify([original]));assert.equal(a.run('startReceiptEdit(1)'),true);if(removal==='zero'){a.element(field).value='0';a.input(field);a.flush();}else a.run(`removeMaterial(${JSON.stringify(id)})`);a.run('saveData()');const cleared=JSON.parse(a.store.get('master_calc_palette_history_final'))[0];assert.deepEqual(cleared.materialLines,[]);assert.deepEqual(cleared.catalogSnapshot,[{id,name:'Исторический материал',unit:'г',unitPrice:1.25}]);assert.deepEqual(cleared.revisions[0],original);a.store.set('master_calc_palette_settings_final',JSON.stringify({hour:9999,pEstel:999}));const b=app({store:a.store});b.boot();assert.equal(b.run('startReceiptEdit(1)'),true);const c=app({store:b.store});c.boot();assert.ok(c.run('editSession'));c.run(`chooseMaterial(${JSON.stringify(id)})`);c.element(field).value='20';c.input(field);c.flush();assert.equal(c.run('currentCalc.materialLines[0].unitPrice'),1.25);assert.equal(c.run('currentCalc.materialLines[0].cost'),25);c.run('saveData()');const history=JSON.parse(c.store.get('master_calc_palette_history_final'));const payload={app:'master-calc',schemaVersion:3,history,settings:JSON.parse(c.run('JSON.stringify(getSettings())')),config:JSON.parse(c.run('JSON.stringify(getConfig())'))};const d=app();d.boot();d.run('globalThis.importInput={files:[],value:"file"}');d.run('importInput').files.push({size:100,text:async()=>JSON.stringify(payload)});await d.run('importBackup(importInput)');assert.deepEqual(JSON.parse(d.store.get('master_calc_palette_history_final')),history);assert.equal(d.run('startReceiptEdit(1)'),true);assert.equal(d.run('currentCalc.materialLines[0].unitPrice'),1.25);assert.equal(d.run('calculationConfig().catalog.length'),1);assert.equal(a.submitted+b.submitted+c.submitted+d.submitted,0);}});
test('unpriced zero legacy placeholders never create missing DOM fields or invented prices',()=>{const a=app();a.boot();a.store.set('master_calc_palette_history_final',JSON.stringify([receipt(1,{rates:JSON.parse(a.run('JSON.stringify(getSettings())')),raw:{wTime:1,gE:0,customQuantities:{'unknown-old':0}},materialLines:[]})]));assert.equal(a.run('startReceiptEdit(1)'),true);assert.equal(a.run('Object.keys(customQuantities).length'),0);assert.ok(a.run('currentCalc'));a.run('saveData()');const saved=JSON.parse(a.store.get('master_calc_palette_history_final'))[0];assert.deepEqual(saved.catalogSnapshot,[]);assert.deepEqual(saved.raw.customQuantities,{});assert.equal(a.run('startReceiptEdit(1)'),true);});

// Consolidated final audit F1/F2/F3.
test('prospective save disclosure follows edit/new context and Google setting across cancel and successful correction',()=>{for(const populated of [false,true]){const a=app();a.boot();a.run('calculate();saveData()');const id=JSON.parse(a.store.get('master_calc_palette_history_final'))[0].id;if(populated){a.element('calc-client-name').value='Следующий';a.element('m-estel').value='20';a.input('m-estel');a.flush();}a.run(`startReceiptEdit(${id})`);assert.match(a.element('save-status').innerText,/без повторной отправки/);a.run('cancelReceiptEdit()');assert.match(a.element('save-status').innerText,/Google Forms.*попытка отправки/);assert.doesNotMatch(a.element('save-status').innerText,/Изменения сохранятся|не отправлялся/);a.run(`startReceiptEdit(${id});calculate();saveData()`);assert.match(a.element('save-status').innerText,/Google Forms.*попытка отправки/);assert.match(a.element('save-result').innerText,/Изменения чека сохранены/);assert.equal(a.submitted,1);a.element('google-send').checked=false;a.run('saveGooglePreference()');assert.match(a.element('save-status').innerText,/отключена/);a.run(`startReceiptEdit(${id})`);assert.match(a.element('save-status').innerText,/без повторной отправки/);a.run('cancelReceiptEdit();startNewCalculation()');assert.match(a.element('save-status').innerText,/отключена/);a.element('google-send').checked=true;a.run('saveGooglePreference()');assert.match(a.element('save-status').innerText,/Google Forms.*попытка отправки/);assert.equal(a.run('googleSendEnabled()'),true);}});
test('saving template retains valid manual quote raw draft and first receipt save while recipe excludes override',()=>{const a=app();a.boot();a.run('const existing=getConfig();existing.templates.push({id:1,name:"Исходный",raw:{}});persistConfig(existing);calculate(false,true)');a.element('service-template').value='1';a.element('calc-client-name').value='Не потерять';a.element('m-estel').value='60';a.element('actual-price-enabled').checked=true;a.element('actual-price').value='234.56';a.input('actual-price');a.flush();a.element('template-name').value='Состав';a.input('template-name');const raw=a.run('JSON.stringify(currentCalc.raw)'),prior=JSON.parse(a.store.get(DRAFT_KEY));a.run('saveTemplate()');assert.ok(a.run('currentCalc'));assert.equal(a.run('JSON.stringify(currentCalc.raw)'),raw);assert.equal(a.element('res-box').style.display,'block');assert.equal(a.element('save-receipt').disabled,false);assert.equal(a.element('calc-client-name').value,'Не потерять');assert.equal(a.element('actual-price-enabled').checked,true);assert.equal(a.element('service-template').value,'1');assert.deepEqual(JSON.parse(a.store.get(DRAFT_KEY)),prior);assert.equal(JSON.parse(a.store.get(DRAFT_KEY)).actualPrice.value,prior.actualPrice.value);assert.equal(JSON.parse(a.store.get('master_calc_palette_config_v3')).templates.at(-1).raw.actualPrice,undefined);a.run('saveData()');assert.equal(JSON.parse(a.store.get('master_calc_palette_history_final'))[0].total,234.56);});
test('update confirmation describes saved history/draft survival and allows failed-persistence warning',()=>{const a=app();a.boot();a.element('calc-client-name').value='Черновик';a.input('calc-client-name');a.failWrites();a.element('work-time').value='2';a.input('work-time');a.confirm(false);a.run('updateRegistration={waiting:{postMessage(){}}};activateUpdate()');const prompt=a.confirmations[0];assert.match(prompt,/перезагрузится/);assert.match(prompt,/сохранённые история и черновик останутся/);assert.match(prompt,/не удалось сохранить.*могут потеряться/);assert.doesNotMatch(prompt,/расчёт будет сброшен/);assert.match(a.element('draft-message').innerText,/Не удалось сохранить/);});
